graph BankAccount {
    configure { readable: :balance }
    balance: 0
    owner: "Unknown"

    fn deposit(amount) {
        if amount <= 0 {
            raise ValueError("Deposit must be positive")
        }
        balance = balance + amount
    }

    fn withdraw(amount) {
        if amount <= 0 {
            raise ValueError("Withdrawal must be positive")
        }
        if amount > balance {
            raise ValueError("Insufficient funds")
        }
        balance = balance - amount
    }
}

acct = BankAccount { balance: 1000, owner: "Alice" }
acct.deposit(500)
print(acct.balance())  # 1500
acct.withdraw(200)
print(acct.balance())  # 1300

try {
    acct.withdraw(5000)
} catch ValueError as e {
    print(e.message())  # "Insufficient funds"
}

